package com.company.skillplatform.compatibility.interfaces;import com.company.skillplatform.compatibility.application.CompatibilityService;import com.company.skillplatform.compatibility.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.List;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")public class CompatibilityController{private final CompatibilityService service;public CompatibilityController(CompatibilityService s){service=s;}
 @GetMapping("/skill-versions/{id}/compatibilities")List<CompatibilityService.CompatibilityView> list(@PathVariable Long id){return service.list(id);}
 @PutMapping("/skill-versions/{id}/compatibilities")List<CompatibilityService.CompatibilityView> replace(@PathVariable Long id,@Valid@RequestBody ReplaceRequest r,Authentication a){return service.replace(id,r.versionNo,r.compatibilities.stream().map(c->new CompatibilityService.CompatibilityCommand(c.platform,c.agent,c.osType,c.required,c.declaredStatus,c.minPlatformVersion,c.maxPlatformVersion,c.overlayPath)).toList(),(Long)a.getPrincipal());}
 @PostMapping("/skill-versions/{id}/compatibilities:validate")List<CompatibilityService.CompatibilityView> validate(@PathVariable Long id,Authentication a){return service.validate(id,(Long)a.getPrincipal());}
 @GetMapping("/platforms")List<CompatibilityService.PlatformView> platforms(){return service.platforms();}
 public record ReplaceRequest(@NotNull Integer versionNo,@NotNull List<@Valid CompatibilityRequest>compatibilities){}public record CompatibilityRequest(@NotBlank String platform,String agent,@NotNull OsType osType,boolean required,@NotNull CompatibilityStatus declaredStatus,String minPlatformVersion,String maxPlatformVersion,String overlayPath){}
}
